mapper.sql:
WHERE c.teacher_id = #{teacherId}
  AND ar.status = 0

    AND c.course_id = #{query.courseId}


    AND stu.admin_class = #{query.adminClass}


    AND (
        stu.student_number LIKE CONCAT('%', #{query.keyword}, '%')
        OR usr.real_name LIKE CONCAT('%', #{query.keyword}, '%')
    )


    AND sess.start_time >= CONCAT(#{query.startDate}, ' 00:00:00')


    AND sess.start_time <= CONCAT(#{query.endDate}, ' 23:59:59')

WHERE n.teacher_id = #{teacherId}
  AND n.send_status = 1

    AND n.course_id = #{query.courseId}


    AND stu.admin_class = #{query.adminClass}


    AND (
        stu.student_number LIKE CONCAT('%', #{query.keyword}, '%')
        OR usr.real_name LIKE CONCAT('%', #{query.keyword}, '%')
    )


    AND n.send_time >= CONCAT(#{query.startDate}, ' 00:00:00')


    AND n.send_time <= CONCAT(#{query.endDate}, ' 23:59:59')
